(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[3467],{3576:(e,l,a)=>{"use strict";a.r(l),a.d(l,{data:()=>t});const t={key:"v-885c30f8",path:"/pages/self-daily/daily-log/2025-09-01/",title:"",lang:"zh-CN",frontmatter:{sidebar:!1},excerpt:"",headers:[{level:3,title:"暑假结束了",slug:"暑假结束了",children:[]}],filePathRelative:"pages/self-daily/daily-log/2025-09-01/README.md",git:{updatedTime:1756816976e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:2}]}}},2659:(e,l,a)=>{"use strict";a.r(l),a.d(l,{default:()=>i});var t=a(6252);const s=(0,t.Wm)("h3",{id:"暑假结束了"},[(0,t.Wm)("a",{class:"header-anchor",href:"#暑假结束了"},"#"),(0,t.Uk)(" 暑假结束了")],-1),r=(0,t.Wm)("p",null,"   醒醒你早就没有暑假了，今天是九月一号，读书时代，现在该开学了，开学意味着暑假作业写得怎么样了，虽然我从来没有完成过一次完完整整的暑假作业。还记得有一次，去报名的时候老师要交暑假作业，我就说忘记带了，其实是根本没有动，于是乎回家之后花了一个通宵，抄完了几本暑假作业。然后等上学的第一天老师也没有要收暑假作业。当时感觉自己就是一头驴。哈哈。新学期的开学往往要升一个年级了，这是会有开学典礼。这是我最讨厌也最期望的，讨厌是那些领奖的人，从来不是我，（虽然后面初二的时候领过一次，不过那个时候我成绩也是第四名按理应该是前三名拿，还是老师给了我这个机会）期望的是可以一个下午不上学。转眼间十几年过去了，现在也不再拥有暑假了，每天都是工作日。    现在每天都工作 12 个小时，有时候有事情做时间还会过得快一点，如果事情少就感觉时间过得非常得慢了。有时侯也会感觉挺累的，但是想想这些年自己为了啥，又总会咬咬牙继续坚持。过两天就可以看阅兵了，阅兵对于一个男人来说的吸引力可以说是无可比拟的。9 月 3 号，抗日战争胜利 80 周年阅兵。我要早早定好闹钟准备好观看一分钟都不落下。",-1),i={render:function(e,l){return(0,t.wg)(),(0,t.j4)(t.HY,null,[s,r],64)}}}}]);